import{_ as s,l as i,o as e,c as l,v as t,p as P,x as r,d as p,i as d,S as n}from"./chunks/framework.InCnrqk-.js";const U=JSON.parse('{"title":"UDP","description":"","frontmatter":{"title":"UDP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/udp.md","filePath":"cs/udp.md","lastUpdated":1789023840000}'),c={name:"cs/udp.md"};function h(D,a,m,_,u,A){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="udp" tabindex="-1">UDP <a class="header-anchor" href="#udp" aria-label="Permalink to &quot;UDP&quot;">​</a></h1><div class="epigraph"><p>UDP 只提供端口与可选校验和：把 IP 的主机到主机，延伸成进程到进程的数据报。</p><footer>—— 据 Postel, RFC 768, User Datagram Protocol, 1980 整理</footer></div><p><a href="/cs/bgp-policy">上一课</a>能把分组交到一台主机。<a href="/cs/process-image">进程映像</a>上却跑着许多程序。<a href="/cs/file-bytestream">文件描述符</a>还没有接到网络。缺口是传输层最薄的一种：<strong>UDP</strong>——端口、长度、校验和，不保证序与到达。本课不把 TCP 握手提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IP 的协议号指向「哪一种传输」，但内核还要知道交给哪个套接字。16 位源/目的端口与四元组（后课 TCP 再加）标识端点。若在 UDP 里做可靠，每个应用重写一套——有人愿意（DNS、RTP），有人把可靠下放到 TCP。缺口是这个最小数据报服务，符合<a href="/cs/layering-e2e">端到端</a>：不把文件语义塞进这一层。</p><p>本课不把 QUIC 在 UDP 上的复用写完。</p><p><span class="marginnote">校验和覆盖伪头（含 IP 地址），检测误投。IPv6 上 UDP 校验和不可全关。无连接：发送前不必握手。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>sendto</code>：内核加 UDP 头，交给 IP。<a href="/cs/icmp">ICMP</a> 端口不可达可回来，也可被过滤。MTU：UDP 不自动重传；分片由 IP（v4）或由应用避开。DNS 与 DHCP 已在前课出现，它们正是 UDP 载荷。</p>',9)),(e(),P(n,null,{default:r(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROC%5B%22%E8%BF%9B%E7%A8%8B%E7%AB%AF%E5%8F%A3%22%5D%20--%3E%20UDP%5B%22UDP%20%E6%95%B0%E6%8D%AE%E6%8A%A5%22%5D%0A%20%20UDP%20--%3E%20IP%5B%22IP%20%E5%B0%BD%E5%8A%9B%E8%80%8C%E4%B8%BA%22%5D%0A%20%20IP%20--%3E%20DEMUX%5B%22%E7%9B%AE%E7%9A%84%E7%AB%AF%E5%8F%A3%E8%A7%A3%E5%A4%8D%E7%94%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>UDP 把<a href="/cs/socket-api">套接字</a>（后课）接到 IP，而不引入连接表。丢失、重复、乱序原样交给应用。拥塞：UDP 默认不减速，所以后课 TCP 友好与实时流量会冲突；本课只承认没有拥塞状态机。NAT 对 UDP 用超时表项，比 TCP 更易过期——接 <a href="/cs/dhcp-nat">NAT</a> 课。</p><p>与管道对照：管道在单机内核缓冲里可靠；UDP 跨机，缓冲只在两端套接字，中间是网络。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 UDP-Lite 部分覆盖。不把 STUN/TURN 写成完整 NAT 穿越教程。可靠字节流、握手、重传是 TCP 三课的缺口；下一课先握手。</p><p>连接字面：<code>connect</code> 在 UDP 上只记下默认对端，并不握手。错误（ICMP）可以投递到该套接字。</p><p>校验和为 0 在 IPv4 表示不校验；静默错误会交给应用，这是薄传输的代价。</p><p>后课默认：进程可用端口收发无连接数据报。需要连接与可靠时，下一课 TCP 三次握手。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>UDP（RFC 768）= 端口 + 可选校验，无握手无重传。</li><li>解复用到进程；可靠性按端到端留给应用或 TCP。</li><li>连接建立是下一课。</li><li>出处：RFC 768；Kurose and Ross；Tanenbaum <em>Computer Networks</em>。</li></ul>',10))])}const f=s(c,[["render",h]]);export{U as __pageData,f as default};
